INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('beiliao','北辽','["大辽","燕京辽"]','契丹','cn','east_asia',1122,1,NULL,'year',1123,12,NULL,'month',13464,13487,'ochre',NULL,NULL,'辽朝末年金军南下，辽宗室与留守官员在燕京拥立耶律淳，1122年建立短暂的北辽。耶律淳死后，萧德妃称制主持政务；金军攻取燕京，北辽于1123年瓦解，萧德妃随后归附天祚帝。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dongliao','东辽','["辽"]','契丹','cn','east_asia',1213,1,NULL,'year',1269,12,NULL,'month',14556,15239,'ochre',NULL,NULL,'1213年耶律留哥称辽王；1269年耶律古乃去职，广宁并入东京。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xiliao','西辽','["大辽","哈剌契丹","黑契丹"]','契丹','cn','east_asia',1124,1,NULL,'year',1218,12,NULL,'month',13488,14627,'ochre',NULL,NULL,'辽亡前后，宗室耶律大石率部西行，依托可敦城及漠北诸部整军；此后进入中亚，以巴拉沙衮为中心建立西辽，又称哈剌契丹。西辽控制中亚绿洲与商路，1141年卡特万之战后势力扩展至河中地区；此后因内乱和屈出律夺权而衰弱，1218年为蒙古所灭。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qu-chulu','屈出律','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乃蛮王子，娶耶律直鲁古之女后夺取西辽权位。其统治引发当地穆斯林反抗，蒙古军西征时攻入西辽，屈出律于1218年被俘处死，政权灭亡；在位1211—1218年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/屈出律"}]',NULL,NULL,'西辽皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-defei','萧德妃','beiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃","政治家"]','耶律淳妃，耶律淳死后临朝称制，北辽旋亡；金军攻取燕京后她与耶律大石离开，后来归附天祚帝并被杀，北辽后续划分有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧德妃"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-tabuyan','萧塔不烟','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝","政治家"]','耶律大石遗孀，西辽感天皇后。大石死后她以摄政者身份维持政权，并在其子耶律夷列成年后交还权力；临朝称制1143—1150年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧塔不烟"}]',NULL,NULL,'感天皇后','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-li-shi','姚里氏','dongliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["王后","政治家"]','耶律留哥妻，元史立为妃；留哥卒后佩虎符权领其众七年，请以嫡子薛阇袭爵。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚里氏"}]',NULL,NULL,'王后','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-chun','耶律淳','beiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','辽朝宗室，金军南下时在燕京被拥立为帝，建立短暂的北辽政权，与天祚帝所代表的辽廷并存。其去世后北辽迅速失去凝聚力，燕京亦于1122年被金军攻取；在位1122年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律淳"}]',NULL,NULL,'北辽皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-dashi','耶律大石','xiliao','[]',NULL,NULL,1087,1,NULL,'year',1143,1,NULL,'year','["皇帝"]','辽太祖后裔，辽亡后率部西行，联结西域势力并于1124年前后建立西辽，号葛儿汗。其政权以巴拉沙衮为中心，控制中亚绿洲与交通要地；在位1124—1143年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律大石"},{"label":"遼史/卷30","url":"https://zh.wikisource.org/wiki/遼史/卷30"}]',NULL,'德宗','西辽德宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-gunai','耶律古乃','dongliao','[]',NULL,NULL,1234,1,NULL,'year',1269,1,NULL,'year','["君主"]','耶律收国奴长子，1259年嗣爵；至元六年广宁并入东京，去职同年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律古乃"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-liuge','耶律留哥','dongliao','[]',NULL,NULL,1165,1,NULL,'year',1220,1,NULL,'year','["君主"]','金末契丹将领，1213年称辽王、国号辽，改元天统；拒称帝，蒙古仍封辽王。史称东辽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律留哥"},{"label":"元史/卷149","url":"https://zh.wikisource.org/wiki/元史/卷149"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-pusuwan','耶律普速完','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝","政治家"]','耶律夷列之妹，西辽承天太后，兄长死后以摄政身份掌政。她在宫廷冲突中被处死，耶律直鲁古随后即位；临朝称制1163—1177年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律普速完"}]',NULL,NULL,'承天太后','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-shouguonu','耶律收国奴','dongliao','[]',NULL,NULL,1215,1,NULL,'year',1259,1,NULL,'year','["君主"]','耶律薛阇之子，1238年袭爵，行广宁府路总管军民万户府事，易名石剌。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律收国奴"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-sibu','耶律厮不','dongliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["宗室"]','留哥属下郡王，1216年僭帝号于澄州，国号辽、改元天威，史称后辽；月余被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律厮不"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-xieshe','耶律薛阇','dongliao','[]',NULL,NULL,1193,1,NULL,'year',1238,1,NULL,'year','["君主"]','耶律留哥嫡长子，1226年袭辽王爵，后行广宁路都元帅府事。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律薛阇"}]',NULL,NULL,'辽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-yilie','耶律夷列','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','耶律大石之子、萧塔不烟之后的西辽君主，承接父辈在中亚建立的统治。其在位期间西辽继续控制七河与河中部分地区；在位1150—1163年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律夷列"}]',NULL,'仁宗','西辽仁宗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yelu-zhilugu','耶律直鲁古','xiliao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','耶律夷列之子、耶律普速完之后继位，统治西辽后期。乃蛮王子屈出律借婚姻与宫廷政变夺权，直鲁古被废，西辽逐渐走向覆亡；在位1177—1211年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/耶律直鲁古"}]',NULL,NULL,'西辽皇帝','[]');
